mapper.select:
SELECT COUNT(1)
FROM meeting_book
WHERE room_id = #{roomId}
  AND status IN

    #{status}

  AND start_time < #{endTime}
  AND end_time > #{startTime}

    AND id <> #{excludeId}

SELECT
FROM meeting_book b LEFT JOIN meeting_room r ON b.room_id = r.id LEFT JOIN `user` u ON b.user_id = u.id WHERE b.user_id = #{userId}
AND b.status = #{status}
ORDER BY b.create_time DESC

SELECT
FROM meeting_book b LEFT JOIN meeting_room r ON b.room_id = r.id LEFT JOIN `user` u ON b.user_id = u.id
AND b.status = #{status}
AND b.room_id = #{roomId}
AND (u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR b.purpose LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY b.status ASC, b.create_time DESC

mapper.update:
UPDATE meeting_book
SET status     = #{status},
    audit_msg  = #{auditMsg},
    audit_time = #{auditTime}
WHERE id = #{id}

UPDATE meeting_book
SET status        = #{status},
    cancel_reason = #{cancelReason},
    cancel_time   = #{cancelTime}
WHERE id = #{id}

UPDATE meeting_book
SET status = #{toStatus}
WHERE status = #{fromStatus}
  AND end_time < NOW()
